<?php get_header();$term=get_queried_object();$parent=$term->parent?get_term($term->parent,'product_cat'):$term;pt_breadcrumb();$h1=get_term_meta($term->term_id,'pt_h1',true)?:$term->name; ?><style>
.compact{padding:0}.category-tabs{justify-content:center;flex-wrap:wrap;overflow:visible;padding:16px 25px}.category-tabs>*{flex:0 0 auto;white-space:normal}.compact+section{padding:26px 0 22px}.compact+section+section#range{padding-top:30px}
</style>
<section class="hero categoryhero" style="--hero-image:url('<?php echo esc_url(pt_term_image($parent)); ?>')"><div class="wrap"><div class="hero-copy"><span class="eyebrow">PRODUCTS & SOLUTIONS</span><h1><?php echo esc_html($h1); ?></h1><p><?php echo esc_html($term->description?:'Explore this product range and discuss your sourcing requirements.'); ?></p><div class="actions"><a class="btn light" href="#range">Explore the range</a><a class="btn outline" href="<?php echo esc_url(home_url('/request-a-quote/')); ?>">Request a Quote</a></div></div></div></section>
<section class="compact"><div class="wrap category-tabs"><?php foreach(pt_cats() as $c)echo '<a class="'.($c->term_id===$parent->term_id?'current':'').'" href="'.esc_url(get_term_link($c)).'">'.esc_html($c->name).'</a>'; ?></div></section>
<?php if($intro=get_term_meta($term->term_id,'pt_intro',true))echo '<section><div class="wrap narrow">'.wpautop(esc_html($intro)).'</div></section>'; ?><section id="range"><div class="wrap"><span class="eyebrow">EXPLORE THE RANGE</span><h2>Explore Our <?php echo esc_html($parent->name); ?> Range</h2><div class="range-grid"><?php foreach(get_terms(['taxonomy'=>'product_cat','parent'=>$parent->term_id,'hide_empty'=>false,'orderby'=>'term_id']) as $i=>$c)echo '<article class="range-card"><span class="range-icon">'.pt_icon($c->slug).'</span><h3><a href="'.esc_url(get_term_link($c)).'">'.esc_html($c->name).'</a></h3><p>'.esc_html(pt_range_description($c->slug)).'</p><a class="text-link" href="'.esc_url(get_term_link($c)).'">View products →</a></article>'; ?></div></div></section>
<section class="pale" id="catalogue"><div class="wrap"><div class="section-top"><div><span class="eyebrow">PRODUCT CATALOGUE</span><h2>Featured Products</h2></div><?php if(pt_local())echo '<p>Clearly labelled samples demonstrate browsing.<br>Verified catalogue import is pending.</p>'; ?></div><form class="filter-form" method="get" action="#catalogue"><label>Subcategory<select name="filter"><option value="">All subcategories</option><?php foreach(get_terms(['taxonomy'=>'product_cat','parent'=>$parent->term_id,'hide_empty'=>false]) as $c)echo '<option value="'.esc_attr($c->slug).'" '.selected(sanitize_title($_GET['filter']??''),$c->slug,false).'>'.esc_html($c->name).'</option>'; ?></select></label><label>Search this range<input name="q" type="search" value="<?php echo esc_attr(sanitize_text_field($_GET['q']??'')); ?>"></label><button class="btn">Apply filters</button><a class="text-link" href="<?php echo esc_url(get_term_link($term)); ?>#catalogue">Reset</a></form>
<?php $selected=sanitize_title($_GET['filter']??'');$filter=$selected?get_term_by('slug',$selected,'product_cat'):false;$tid=$filter&&term_is_ancestor_of($parent->term_id,$filter->term_id,'product_cat')?$filter->term_id:$term->term_id;$page=max(1,(int)get_query_var('paged'));$args=['post_type'=>'product','post_status'=>'publish','posts_per_page'=>8,'paged'=>$page,'tax_query'=>[['taxonomy'=>'product_cat','terms'=>[$tid],'include_children'=>true]],'meta_query'=>pt_sample_query(),'orderby'=>'title','order'=>'ASC'];if(!empty($_GET['q']))$args['s']=sanitize_text_field($_GET['q']);$query=new WP_Query($args);echo '<p role="status">'.(int)$query->found_posts.' products found</p>';if($query->have_posts())pt_cards($query->posts);else echo '<div class="empty-state"><h3>No matching products</h3><p>Try a broader range or tell us what you need.</p></div>';echo '<nav class="pagination" aria-label="Product pages">'.paginate_links(['base'=>trailingslashit(get_term_link($term)).'page/%#%/','format'=>'','current'=>$page,'total'=>$query->max_num_pages]).'</nav>'; ?></div></section>
<?php pt_supply_links($parent->slug);pt_related_projects($parent->slug);pt_faq('/products/'.$parent->slug.'/');pt_cta();get_footer(); ?>
